   {'t': 'North Carolina 1965', 'v': 46.8, 'lab': '46.8%', 'open': True, 'acc': True, 'plate': {'kicker': 'US7.6 · Greensboro', 'title': 'The sit-ins', 'sub': 'February to April 1960', 'text': "[[c-us7-cr2-sitins]]", 'sources': ['us7b-ki-sitins']}},
   {'t': 'North Carolina 1988', 'v': 58.2, 'lab': '58.2%'},
   {'t': 'South Carolina 1965', 'v': 37.3, 'lab': '37.3%', 'open': True},
   {'t': 'South Carolina 1988', 'v': 56.7, 'lab': '56.7%'},
   {'t': 'Virginia 1965', 'v': 38.3, 'lab': '38.3%', 'open': True},
