   {'t': '1967', 'sub': 'start of Wimer series', 'v': 14.2, 'lab': '14.2%', 'acc': True, 'plate': {'kicker': 'US7.7 · measures', 'title': 'Counting the poor', 'sub': 'Wimer; Burkhauser', 'text': "[[c-us7-gs-wimer]] [[c-us7-gs-burk]]", 'sources': ['us7b-wimer-2016', 'us7b-nber-burk']}},
   {'t': '1968', 'v': 12.8, 'lab': '12.8%'},
   {'t': '1969', 'v': 12.1, 'lab': '12.1%'},
